// Populate the exact retained R15 shipping Runtime through its owner IPC.
// Current storage APIs are deliberately not opened before the upgrade.
#include "ftn_current_installed_client.inc"
#include "network_setup_fixture.hpp"
#include "sfx/platform/win32/ftn_secrets.hpp"
#include "sqlite_internal.hpp"
#include <fstream>
namespace {
app::FtnConfigurationResponse ftn_exchange(RuntimeSession& runtime,const app::FtnConfigurationRequest& q){const auto bytes=runtime.exchange(app::LocalControlMessageType::ftn_configuration_request,app::LocalControlMessageType::ftn_configuration_response,app::encode_ftn_configuration_request(q));const auto result=app::decode_ftn_configuration_response(bytes);check(result.has_value(),"typed predecessor FTN response");return *result;}
app::FtnConfiguration read_ftn(RuntimeSession& runtime){app::FtnConfigurationRequest q;q.token=token();std::vector<std::uint8_t> bytes;std::uint32_t total{};do{const auto p=ftn_exchange(runtime,q);check(p.code==app::FtnConfigurationCode::ok&&p.offset==bytes.size()&&!p.bytes.empty(),"pinned predecessor FTN page");if(!q.revision){q.revision=p.revision;total=p.total;}check(p.revision==q.revision&&p.total==total,"same predecessor snapshot");bytes.insert(bytes.end(),p.bytes.begin(),p.bytes.end());q.offset=static_cast<std::uint32_t>(bytes.size());}while(bytes.size()<total);q.operation=app::FtnConfigurationOperation::cancel;q.offset=0;check(ftn_exchange(runtime,q).code==app::FtnConfigurationCode::ok,"release predecessor FTN snapshot");const auto c=app::decode_ftn_configuration(bytes);check(c.has_value(),"decode predecessor configuration");return *c;}
void save_ftn(RuntimeSession& runtime,const app::FtnConfiguration& c){const auto bytes=app::encode_ftn_configuration(c);check(!bytes.empty(),"valid predecessor draft");app::FtnConfigurationRequest q;q.token=token();q.operation=app::FtnConfigurationOperation::begin;q.revision=c.revision;q.total=static_cast<std::uint32_t>(bytes.size());check(ftn_exchange(runtime,q).code==app::FtnConfigurationCode::ok,"stage predecessor owner draft");q.operation=app::FtnConfigurationOperation::append;for(std::size_t at=0;at<bytes.size();at+=app::kFtnConfigurationPageBytes){q.offset=static_cast<std::uint32_t>(at);const auto end=std::min(bytes.size(),at+app::kFtnConfigurationPageBytes);q.bytes={bytes.begin()+at,bytes.begin()+end};check(ftn_exchange(runtime,q).code==app::FtnConfigurationCode::ok,"ordered predecessor owner page");}q.operation=app::FtnConfigurationOperation::commit;q.offset=0;q.bytes.clear();check(ftn_exchange(runtime,q).code==app::FtnConfigurationCode::ok,"predecessor owner commit");}
}
int main(int argc,char** argv)try{
    check(argc==2||(argc==3&&std::string_view(argv[2])=="--verify-only"),"new bootstrap evidence directory or read-only verification");const bool verify_only=argc==3;const auto out=std::filesystem::absolute(argv[1]);check(!std::filesystem::exists(out),"preserve previous bootstrap evidence");std::filesystem::create_directories(out);
    const auto root=ins::canonical_root(network_setup_qualification_root());const auto owner=ins::operator_sid();check(!ins::elevated(),"ordinary owner only");ins::verify_runtime_installation(root,owner);
    if(!verify_only){RuntimeSession runtime(root,true);app::AlphaBootstrapRequest request;request.configuration.bbs_name="Toss Fix Qualification";request.configuration.bbs_time_zone="Pacific Standard Time";request.configuration.logical_nodes=4;request.configuration.telnet.bind_address="127.0.0.1";request.configuration.telnet.port=26531;request.configuration.telnet.bot_gate_enabled=false;request.configuration.botgate.enabled=false;request.configuration.ssh.enabled=true;request.configuration.ssh.bind_address="127.0.0.1";request.configuration.ssh.port=26532;request.sysop_name="Import Fixture";request.sysop_password="Synthetic-owner-only-123";request.system_password="Synthetic-system-only-456";
        const auto status=app::read_status_snapshot(0,[&](const app::AlphaStatusRequest& q)->std::optional<std::vector<std::uint8_t>>{return runtime.exchange(app::LocalControlMessageType::status_request,app::LocalControlMessageType::status_response,app::encode_status_request(q));});check(status&&runtime.tracker.accept(*status),"predecessor security snapshot");request.configuration.security_policy_revision=status->security_policy_revision;request.configuration.security_policy_hash=status->security_policy_hash;const auto raw=app::encode_bootstrap_request(request);check(!raw.empty(),"valid first-run request");const auto response=app::decode_control_response(runtime.exchange(app::LocalControlMessageType::bootstrap_request,app::LocalControlMessageType::bootstrap_response,raw));app::erase_bootstrap_secrets(request);check(response&&response->code==app::LocalControlResponseCode::ok,"normal predecessor first-run setup");
        for(const auto* name:{"FidoNet","X-League"}){const auto before=app::decode_message_configuration_snapshot(runtime.exchange(app::LocalControlMessageType::message_configuration_query_request,app::LocalControlMessageType::message_configuration_query_response,app::encode_message_configuration_query({})));check(before&&before->code==app::LocalAccountResultCode::ok,"predecessor saved catalog");app::MessageConfigurationChange change;change.operation.bytes=token();change.action=app::MessageConfigurationAction::group;change.expected_configuration_revision=before->catalog.revision;change.group.name=name;change.group.access=10;const auto saved=app::decode_message_configuration_result(runtime.exchange(app::LocalControlMessageType::message_configuration_change_request,app::LocalControlMessageType::message_configuration_change_response,app::encode_message_configuration_change(change)));check(saved&&saved->code==app::LocalAccountResultCode::ok,"predecessor named group saved");}
        auto c=read_ftn(runtime);check(c.networks.empty(),"fresh predecessor FTN configuration");c.settings.listener_enabled=c.settings.tls_listener_enabled=false;c.settings.bind_address="127.0.0.1";
        app::FtnNetwork fido;fido.code="FIDO";fido.name="FidoNet";fido.address="42:100/49";fido.enabled=true;fido.default_link="HUB";c.networks.push_back(fido);auto other=fido;other.code="XL";other.name="X-League";other.address="64200:100/49";other.default_link.clear();c.networks.push_back(other);
        app::FtnLink hub;hub.network="FIDO";hub.code="HUB";hub.name="FidoNet-Hub";hub.address="42:100/1";hub.host="127.0.0.1";hub.port=26539;hub.enabled=true;hub.contact_on_mail=false;hub.credentials.session=*win::protect_ftn_secret(root.u8string(),hub.network,hub.code,win::FtnCredentialKind::session,"Synthetic-peer-only");c.links.push_back(hub);save_ftn(runtime,c);const auto saved=read_ftn(runtime);check(saved.networks.size()==2&&saved.links.size()==1&&saved.message_echoes.empty(),"populated predecessor network and protected hub retained");runtime.stop();}
    if(verify_only){RuntimeSession runtime(root,false);const auto saved=read_ftn(runtime);check(saved.networks.size()==2&&saved.links.size()==1&&saved.message_echoes.empty()&&!saved.links[0].credentials.session.empty(),"already committed predecessor state verified without repeating first-run writes");runtime.stop();}
    sfx::adapters::storage::internal::SqliteConnection db(root/L"Data/SFX.DB",SQLITE_OPEN_READONLY,std::chrono::milliseconds(100),false);const auto schema=db.scalar_int64("PRAGMA user_version","read predecessor version without migrating");check(schema==26,"actual R16 schema26 remains before normal Setup update");check(db.scalar_int64("SELECT count(*) FROM sfx_message_groups WHERE name IN('FidoNet','X-League')","verify predecessor named groups")==2,"both predecessor groups retained");std::ofstream report(out/L"predecessor.txt");report<<"schema="<<schema<<"\nprograms=12\nnetwork_count=2\nhub_count=1\nverify_only="<<verify_only<<"\n";
    std::cout<<"PASS "<<checks<<" actual R16 schema26 group/network/hub state checks; isolated closed root\n";return 0;
}catch(const std::exception& error){std::cerr<<"FAIL "<<checks<<": "<<error.what()<<'\n';return 1;}
